HARBOR_STATE = {'DLV': 'delivered', 'DLL': 'delivered_late', 'CAN': 'cancelled', 'RET': 'returned', 'HLD': 'held'}


def decode(raw):
    if raw[:2] == b'\x1f\x8b':
        raw = gzip.decompress(raw)
    if raw[:3] == b'\xef\xbb\xbf':
        return raw[3:].decode('utf-8')
    if raw[:2] == b'\xff\xfe':
        return raw[2:].decode('utf-16-le')
    if raw[:2] == b'\xfe\xff':
        return raw[2:].decode('utf-16-be')
    enc = 'utf-8'
    head = raw[:2000].decode('latin-1')
    for line in head.split('\n')[:10]:
        m = re.match(r'#\s*charset\s*:\s*(\S+)', line)
        if m:
            enc = m.group(1)
            break
    try:
        return raw.decode(enc)
    except (LookupError, UnicodeDecodeError):
        return raw.decode('latin-1')


def idnum(s):
    m = re.search(r'\d+', s or '')
    return int(m.group()) if m else None


def norm_status(s):
    return re.sub(r'[\s\-]+', '_', (s or '').strip().lower())


def counted(s):
    return s in ('delivered', 'delivered_late')


def rtype(s):
    s = (s or '').strip().lower()
    if s.startswith('v'):
        return 'void'
    if s.startswith('c') or s.startswith('amend'):
        return 'correction'
    return 'new'


def parse_weight(s, unit, depot=None):
    """Returns kg Decimal. unit is the unit in force; a suffix wins."""
    s = (s or '').strip()
    m = re.match(r'^([0-9.,\s]*[0-9.,])\s*([A-Za-z]*)$', s)
    if not m:
        return None
    num, u = m.group(1).replace(' ', ''), m.group(2).lower()
    if depot == 'west':
        num = num.replace('.', '').replace(',', '.')
    else:
        num = num.replace(',', '')
    if u in KG:
        unit = u
    try:
        return Decimal(num) * KG[unit]
    except Exception:
        return None


def parse_date(s, form):
    s = (s or '').strip()
    if not s:
        return None
    if 'T' in s and re.match(r'\d{4}-\d\d-\d\d', s):
        return parse_dt(s)
    f = (form or 'iso').strip()
    fl = f.lower()
    try:
        if fl == 'serial':
            return date(1899, 12, 31) + timedelta(days=int(float(s)) )  - (timedelta(0))
