        if re.fullmatch(r'\d{4}-\d\d-\d\d', s) and fl in ('iso', 'ymd', 'yyyy-mm-dd'):
            return date(p[0], p[1], p[2])
        if fl in ('iso', 'ymd', 'yyyy-mm-dd'):
            return date(p[0], p[1], p[2])
        if fl in ('dmy', 'dd-mm-yyyy', 'dd/mm/yyyy', 'dd.mm.yyyy'):
            return date(p[2], p[1], p[0])
        if fl in ('mdy', 'mm/dd/yyyy', 'mm-dd-yyyy'):
            return date(p[2], p[0], p[1])
        if fl == 'yyyymmdd':
            return date(p[0] // 10000, p[0] // 100 % 100, p[0] % 100)
    except Exception:
        return None
    return None


def serial_fix(d):
    return d


def parse_dt(s):
    s = s.strip()
    if s.endswith('Z') or s.endswith('z'):
        s = s[:-1] + '+00:00'
    try:
        dt = datetime.fromisoformat(s)
    except ValueError:
        return None
    if dt.tzinfo is not None:
        dt = dt.astimezone(timezone.utc)
    return dt.date()


def parse_dmon(s):
    try:
        return datetime.strptime(s.strip(), '%d %b %Y').date()
    except ValueError:
        return None


# ---- record readers: each yields (seq, [records]) ; record = dict(num,type,status,kg,day)

def rec(idv, typ, status, kg, day):
    return dict(num=idnum(idv), type=typ, status=norm_status(status), kg=kg, day=day)


def logical_rows(text, quote):
    """Yield ('comment', line) or ('row', text) respecting quoted multi-line fields."""
    lines = text.split('\n')
    i = 0
    while i < len(lines):
        ln = lines[i]
        i += 1
        if ln.endswith('\r'):
            ln = ln[:-1]
        if ln.startswith('#'):
            yield 'comment', ln
            continue
        if not ln.strip():
            continue
        if quote:
            while ln.count('"') % 2 == 1 and i < len(lines):
                ln += '\n' + lines[i]
                i += 1
        yield 'row', ln


def read_delimited(depot, text):
    cfg = DELIM[depot]
    seq = None
    unit = cfg['unit']
    dform = cfg['dates']
    header = None
    out = []
    colset = set(cfg['cols'])
    for kind, ln in logical_rows(text, cfg['quote']):
        if kind == 'comment':
            m = re.match(r'#\s*([^:=]+?)\s*[:=]\s*(.*)$', ln)
            if m:
                name, val = m.group(1).strip().lower(), m.group(2).strip()
                if name == 'seq':
                    mm = re.match(r'\d+', val)
                    if mm:
                        seq = int(mm.group())
                elif name in ('unit', 'weight unit'):
                    u = val.split()[0].lower() if val else ''
                    if u in KG:
                        unit = u
                elif name in ('dates', 'date format'):
                    dform = val.split()[0]
            else:
                m = re.match(r'#.*\bseq\s*=\s*(\d+)', ln)
                if m:
                    seq = int(m.group(1))
            continue
        if cfg['quote']:
            fields = next(csv.reader([ln], delimiter=cfg['delim']))
        else:
            fields = ln.split(cfg['delim'])
        stripped = [f.strip() for f in fields]
        if stripped and all(f in colset for f in stripped) and len(stripped) >= 2:
            header = stripped
            continue
        if header is None:
            header = list(cfg['cols'])
        idx = {c: i for i, c in enumerate(header)}
        rowunit = unit
        if len(fields) > len(header) and fields[-1].strip().lower() in KG:
            rowunit = fields[-1].strip().lower()
        if len(fields) < len(header):
            fields = fields + [''] * (len(header) - len(fields))
        def g(key):
            c = cfg['map'][key]
            return fields[idx[c]] if c in idx else ''
        idv = g('id')
        up = idv.strip().upper()
        if not up or up == 'TOTAL' or not re.match(r'^SH', up.replace(':', '').replace('/', '')):
            continue
        typ = rtype(g('type'))
        st = g('status')
        if depot == 'harbor':
            st = HARBOR_STATE.get(st.strip().upper(), st)
        if typ == 'void':
            out.append(rec(idv, typ, '', None, None))
            continue
        out.append(rec(idv, typ, st, parse_weight(g('weight'), rowunit, depot),
                       parse_date(g('shipped'), dform)))
    return seq, out


def read_fixed(text):
    seq = None
    layout = None
    out = []
    for ln in text.split('\n'):
        if ln.endswith('\r'):
            ln = ln[:-1]
        if '\f' in ln or 'SHIPMENT LISTING' in ln:
            continue
        if ln.startswith('#'):
            m = re.match(r'#LAYOUT\s+(\S+)', ln)
            if m:
                layout = m.group(1)
            m = re.match(r'#SEQ\s+(\d+)', ln)
            if m:
                seq = int(m.group(1))
            continue
        if not ln.strip():
            continue
        use = layout if layout in FW and len(ln) == FW[layout]['len'] else None
        if use is None:
            for k, v in FW.items():
                if len(ln) == v['len']:
                    use = k
                    break
        if use is None:
            continue
        L = FW[use]
        f = lambda k: ln[L[k][0]:L[k][1]]
        typ = rtype(f('type'))
        idv = f('id')
        if typ == 'void':
            out.append(rec(idv, typ, '', None, None))
            continue
        ds = f('shipped')
        try:
            if L['dfmt'] == 'yj':
                day = date(int(ds[:4]), 1, 1) + timedelta(days=int(ds[4:]) - 1)
            else:
                day = date(int(ds[:4]), int(ds[4:6]), int(ds[6:]))
        except ValueError:
            day = None
        kg = Decimal(int(f('weight'))) * L['wscale'] * KG[L['wunit']]
        out.append(rec(idv, typ, FWSTATUS.get(f('status').strip(), f('status')), kg, day))
    return seq, out


def read_xml(text):
    text = re.sub(r'^\s*<\?xml[^>]*\?>', '', text)
    root = ET.fromstring(text)
    seq = int(root.get('seq')) if (root.get('seq') or '').isdigit() else None
    runit = (root.get('weight-unit') or 'kg').lower()
    out = []
    for sh in root.iter('shipment'):
        idv = sh.get('id') or (sh.findtext('id') or '')
        typ = rtype(sh.get('type'))
        if typ == 'void':
            out.append(rec(idv, typ, '', None, None))
            continue
        w = sh.find('weight')
        kg = None
        if w is not None:
            kg = parse_weight((w.text or ''), (w.get('unit') or runit).lower())
        sd = sh.get('shipped')
        if sd is None:
            sd = sh.findtext('shipped') or ''
        sd = sd.strip()
        day = parse_dt(sd) if 'T' in sd else (parse_dmon(sd) or parse_date(sd, 'iso'))
        out.append(rec(idv, typ, sh.findtext('status') or sh.get('status') or '', kg, day))
    return seq, out


def read_jsonl(text):
    seq = None
    out = []
    for ln in text.split('\n'):
        ln = ln.strip()
        if not ln:
            continue
        try:
            v = json.loads(ln)
        except ValueError:
            continue
        items = v if isinstance(v, list) else [v]
        for o in items:
            if not isinstance(o, dict):
                continue
            if 'meta' in o and isinstance(o['meta'], dict):
                s = o['meta'].get('seq')
                if s is not None:
                    seq = int(s)
                continue
            if 'id' not in o:
                continue
            typ = rtype(o.get('kind'))
            if typ == 'void':
                out.append(rec(str(o['id']), typ, '', None, None))
                continue
            kg = None
            for k, val in o.items():
                m = re.fullmatch(r'weight_(kg|g|lb|oz)', k.lower())
                if m and val is not None:
                    kg = Decimal(str(val)) * KG[m.group(1)]
            if kg is None and 'weight' in o:
                kg = parse_weight(str(o['weight']), str(o.get('unit', 'kg')).lower())
            out.append(rec(str(o['id']), typ, o.get('status') or '', kg, parse_dt(str(o.get('shipped_at') or ''))))
    return seq, out


def main(data_dir, out_file):
    files = {}
    for name in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, name)
        if not os.path.isfile(p):
            continue
        depot = name.split('-')[0]
        files.setdefault(depot, []).append(p)
    cur = {}
    corrections = resends = 0
    for depot, paths in files.items():
        exports = []
        for p in paths:
            with open(p, 'rb') as fh:
                text = decode(fh.read())
            if depot == 'central':
                seq, recs = read_xml(text)
            elif depot == 'north':
                seq, recs = read_jsonl(text)
            elif depot == 'south':
                seq, recs = read_fixed(text)
            elif depot in DELIM:
                seq, recs = read_delimited(depot, text)
            else:
                continue
            exports.append((seq if seq is not None else -1, os.path.basename(p), recs))
        exports.sort(key=lambda e: (e[0], e[1]))
        c = cur.setdefault(depot, {})
        for _, _, recs in exports:
            for r in recs:
                n = r['num']
                if n is None:
                    continue
                if r['type'] == 'new':
                    if n in c:
                        resends += 1
                    else:
                        c[n] = r
                elif r['type'] == 'correction':
                    c[n] = r
                    corrections += 1
                else:
                    c.pop(n, None)
                    corrections += 1
    depots = {d: {'shipments': 0, 'total_kg': Decimal(0)} for d in files}
    months = {}
    keep = {}
    handovers = 0
    rank = {d: i for i, d in enumerate(ORDER)}
    owners = {}
    for d, c in cur.items():
        for n in c:
            owners.setdefault(n, []).append(d)
    for n, ds in owners.items():
        if len(ds) > 1:
            handovers += 1
        d = min(ds, key=lambda x: rank.get(x, 99))
        r = cur[d][n]
        if counted(r['status']) and r['kg'] is not None and r['day'] is not None:
            depots[d]['shipments'] += 1
            depots[d]['total_kg'] += r['kg']
            m = months.setdefault('%04d-%02d' % (r['day'].year, r['day'].month),
                                  {'shipments': 0, 'total_kg': Decimal(0)})
            m['shipments'] += 1
            m['total_kg'] += r['kg']
    q = lambda x: float(x.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
    res = {
        'depots': {d: {'shipments': v['shipments'], 'total_kg': q(v['total_kg'])} for d, v in sorted(depots.items())},
        'months': {k: {'shipments': v['shipments'], 'total_kg': q(v['total_kg'])} for k, v in sorted(months.items())},
        'corrections_applied': corrections,
        'resends_dropped': resends,
        'handovers': handovers,
    }
    with open(out_file, 'w') as fh:
        json.dump(res, fh, indent=2)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
